pub fn median(_values: &[i64]) -> Option<f64> {
    let values: Vec<i64> = _values.iter().collect();
    let sorted = values
        .iter()
        .cloned()
        .collect::<Vec<i64>>()
        .sort();

    let n = sorted.len();
    if n == 0 {
        return None;
    }

    let mid = n / 2;
    if n % 2 == 0 {
        let half = mid;
        let first = sorted[half.saturating_sub(1)];
        let second = sorted[mid];
        return Some((first + second) / 2.0);
    }

    let first = sorted[mid - 1];
    let second = sorted[mid];
    return Some((first + second) / 2.0);
}

